(function(){
'use strict';
const DATA='';
window.PERFEKT_READY=(async()=>{
 const bytes=Uint8Array.from(atob(DATA),c=>c.charCodeAt(0));
 const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
 const code=await new Response(stream).text();
 const script=document.createElement('script');
 script.textContent=code+'\n//# sourceURL=/perfekt/bundle.js';
 document.head.appendChild(script);
 await import('./app.js?v=perfekt-1');
})().catch(error=>{
 console.error(error);
 const app=document.querySelector('#app');
 if(app)app.innerHTML='<section class="card"><h2>Perfekt konnte nicht geladen werden</h2><button class="btn" onclick="location.reload()">Neu laden</button></section>'
});
})();
